236	+using Microsoft.EntityFrameworkCore;
237	+using Microsoft.EntityFrameworkCore.Design;
238	+
239	+namespace seed_a_backend.Api.Infrastructure;
240	+
241	+/// <summary>
242	+/// Wird ausschließlich von `dotnet ef` zur Design-Zeit verwendet (z. B. `migrations add`).
243	+/// Der Platzhalter-Connection-String muss syntaktisch gültig sein, es wird zur Design-Zeit
244	+/// keine tatsächliche Verbindung aufgebaut. Zur Laufzeit registriert Program.cs den echten
245	+/// DbContext über ConnectionStrings__Default.
246	+/// </summary>
247	+public class AppDbContextFactory : IDesignTimeDbContextFactory<AppDbContext>
248	+{
249	+    public AppDbContext CreateDbContext(string[] args)
250	+    {
251	+        var optionsBuilder = new DbContextOptionsBuilder<AppDbContext>();
252	+        optionsBuilder.UseSqlServer("Server=localhost;Database=DesignTimePlaceholder;Trusted_Connection=True;TrustServerCertificate=True;");
253	+        return new AppDbContext(optionsBuilder.Options);
254	+    }
255	+}
256	diff --git a/seed-a-backend.Api/Infrastructure/SeedDataImporter.cs b/seed-a-backend.Api/Infrastructure/SeedDataImporter.cs
257	new file mode 100644
258	index 0000000..8954282
259	--- /dev/null
260	+++ b/seed-a-backend.Api/Infrastructure/SeedDataImporter.cs
261	@@ -0,0 +1,268 @@
262	+using System.Text.Json;
263	+using Microsoft.EntityFrameworkCore;
264	+using seed_a_backend.Api.Domain;
265	+using seed_a_backend.Api.Infrastructure.SeedModels;
266	+
267	+namespace seed_a_backend.Api.Infrastructure;
268	+
269	+public class SeedDataImporter(AppDbContext db)
270	+{
271	+    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
272	+
273	+    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
274	+    {
275	+        if (await db.Venues.AnyAsync(ct))
276	+        {
277	+            return;
278	+        }
279	+
280	+        if (!File.Exists(jsonFilePath))
281	+        {
282	+            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' wurde nicht gefunden.");
283	+        }
284	+
285	+        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
286	+        SeedDataDto? data;
287	+        try
288	+        {
289	+            data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions);
290	+        }
291	+        catch (JsonException ex)
292	+        {
293	+            throw new InvalidOperationException(
294	+                $"Anfangsdatenbestand '{jsonFilePath}' konnte nicht gelesen werden: {ex.Message}", ex);
295	+        }
296	+
297	+        if (data is null)
298	+        {
299	+            throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
300	+        }
301	+
302	+        await ImportAsync(data, ct);
303	+    }
304	+
305	+    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
306	+    {
307	+        var spielstaetten = data.Spielstaetten
308	+            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'spielstaetten'-Feld.");
309	+        var veranstaltungen = data.Veranstaltungen
310	+            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'veranstaltungen'-Feld.");
311	+
312	+        var venueIds = new HashSet<string>();
313	+        foreach (var venueDto in spielstaetten)
314	+        {
315	+            var venueId = RequireNonNull(venueDto.Id, "Anfangsdatenbestand enthält eine Spielstätte mit fehlender (null) Id.");
316	+            if (!venueIds.Add(venueId))
317	+            {
318	+                throw new InvalidOperationException($"Spielstätte '{venueId}' ist im Anfangsdatenbestand mehrfach vorhanden.");
319	+            }
320	+        }
321	+
322	+        foreach (var eventDto in veranstaltungen)
323	+        {
324	+            var spielstaetteId = RequireNonNull(eventDto.SpielstaetteId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Spielstätten-Id.");
325	+            if (!venueIds.Contains(spielstaetteId))
326	+            {
327	+                throw new InvalidOperationException(
328	+                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{spielstaetteId}'.");
329	+            }
330	+        }
331	+
332	+        var venues = new List<Venue>();
333	+
334	+        foreach (var venueDto in spielstaetten)
335	+        {
336	+            var venueId = RequireNonNull(venueDto.Id, "Anfangsdatenbestand enthält eine Spielstätte mit fehlender (null) Id.");
337	+            var venueName = RequireNonNull(venueDto.Name, $"Spielstätte '{venueId}' hat einen fehlenden (null) Namen.");
338	+            var venue = new Venue { Name = venueName };
339	+            var roomsById = new Dictionary<string, Room>();
340	+
341	+            var raeume = venueDto.Raeume
342	+                ?? throw new InvalidOperationException($"Spielstätte '{venueId}' enthält kein 'raeume'-Feld.");
343	+
344	+            foreach (var roomDto in raeume)
345	+            {
346	+                var roomId = RequireNonNull(roomDto.Id, $"Spielstätte '{venueId}' enthält einen Raum mit fehlender (null) Id.");
347	+                var roomName = RequireNonNull(roomDto.Name, $"Raum '{roomId}' in Spielstätte '{venueId}' hat einen fehlenden (null) Namen.");
348	+
349	+                if (roomDto.Spalten < 1)
350	+                {
351	+                    throw new InvalidOperationException(
352	+                        $"Raum '{roomId}' in Spielstätte '{venueId}' hat eine ungültige Spaltenzahl ({roomDto.Spalten}); erwartet wird mindestens 1.");
353	+                }
354	+
355	+                var aisleColumns = roomDto.Gang?.Spalten ?? new List<int>();
356	+                foreach (var column in aisleColumns)
357	+                {
358	+                    if (column < 1 || column > roomDto.Spalten)
359	+                    {
360	+                        throw new InvalidOperationException(
361	+                            $"Raum '{roomId}': Gang-Spalte '{column}' liegt außerhalb des Sitzplans (1..{roomDto.Spalten}).");
362	+                    }
363	+                }
364	+
365	+                var reihen = roomDto.Reihen
366	+                    ?? throw new InvalidOperationException($"Raum '{roomId}' in Spielstätte '{venueId}' enthält kein 'reihen'-Feld.");
367	+                var rowLabels = reihen
368	+                    .Select(rowLabel => RequireNonNull(
369	+                        rowLabel, $"Raum '{roomId}' in Spielstätte '{venueId}' enthält einen leeren (null) Eintrag in 'reihen'."))
370	+                    .ToList();
371	+
372	+                if (!roomsById.TryAdd(roomId, new Room
373	+                {
374	+                    Name = roomName,
375	+                    RowLabels = rowLabels,
376	+                    ColumnCount = roomDto.Spalten,
377	+                    AisleColumns = aisleColumns,
378	+                }))
379	+                {
380	+                    throw new InvalidOperationException(
381	+                        $"Spielstätte '{venueId}' enthält den Raum '{roomId}' mehrfach.");
382	+                }
383	+
384	+                venue.Rooms.Add(roomsById[roomId]);
385	+            }
386	+
387	+            foreach (var eventDto in veranstaltungen.Where(e => e.SpielstaetteId == venueId))
388	+            {
389	+                var raumId = RequireNonNull(eventDto.RaumId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Raum-Id.");
390	+                if (!roomsById.TryGetValue(raumId, out var room))
391	+                {
392	+                    throw new InvalidOperationException(
393	+                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{raumId}' in Spielstätte '{venueId}'.");
394	+                }
395	+
396	+                if (eventDto.DauerMinuten < 1)
397	+                {
398	+                    throw new InvalidOperationException(
399	+                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Dauer ({eventDto.DauerMinuten} Minuten); erwartet wird mindestens 1.");
400	+                }
401	+
402	+                if (eventDto.Altersfreigabe < 0)
403	+                {
404	+                    throw new InvalidOperationException(
405	+                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Altersfreigabe ({eventDto.Altersfreigabe}); negative Werte sind nicht erlaubt.");
406	+                }
407	+
408	+                var @event = new Event
409	+                {
410	+                    Titel = RequireNonNull(eventDto.Titel, $"Veranstaltung '{eventDto.Id}' hat einen fehlenden (null) Titel."),
411	+                    Beschreibung = RequireNonNull(eventDto.Beschreibung, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Beschreibung."),
412	+                    Zeitpunkt = eventDto.Zeitpunkt,
413	+                    DauerMinuten = eventDto.DauerMinuten,
414	+                    Altersfreigabe = eventDto.Altersfreigabe,
415	+                };
416	+
417	+                var preiskategorien = eventDto.Preiskategorien
418	+                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'preiskategorien'-Feld.");
419	+
420	+                foreach (var priceCategoryDto in preiskategorien)
421	+                {
422	+                    if (priceCategoryDto.Preis < 0)
423	+                    {
424	+                        throw new InvalidOperationException(
425	+                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen negativen Preis ({priceCategoryDto.Preis}).");
426	+                    }
427	+
428	+                    @event.PriceCategories.Add(new PriceCategory
429	+                    {
430	+                        Name = RequireNonNull(
431	+                            priceCategoryDto.Name,
432	+                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen fehlenden (null) Namen."),
433	+                        Preis = priceCategoryDto.Preis,
434	+                    });
435	+                }
436	+
437	+                var belegteSitzplaetze = eventDto.BelegteSitzplaetze
438	+                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'belegteSitzplaetze'-Feld.");
439	+
440	+                var gesehen = new HashSet<(string RowLabel, int ColumnNumber)>();
441	+                foreach (var sitzplatz in belegteSitzplaetze)
442	+                {
443	+                    if (sitzplatz is null)
444	+                    {
445	+                        throw new FormatException(
446	+                            $"Veranstaltung '{eventDto.Id}' enthält einen leeren (null) Eintrag in 'belegteSitzplaetze'.");
447	+                    }
448	+
449	+                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
450	+
451	+                    if (!gesehen.Add((rowLabel, columnNumber)))
452	+                    {
453	+                        throw new InvalidOperationException(
454	+                            $"Veranstaltung '{eventDto.Id}' listet den Sitzplatz '{sitzplatz}' mehrfach in 'belegteSitzplaetze'.");
455	+                    }
456	+
457	+                    if (!room.RowLabels.Contains(rowLabel))
458	+                    {
459	+                        throw new InvalidOperationException(
460	+                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' referenziert die unbekannte Reihe '{rowLabel}' in Raum '{eventDto.RaumId}'.");
461	+                    }
462	+
463	+                    if (columnNumber < 1 || columnNumber > room.ColumnCount)
464	+                    {
465	+                        throw new InvalidOperationException(
466	+                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt außerhalb der Spaltenzahl (1..{room.ColumnCount}) von Raum '{eventDto.RaumId}'.");
467	+                    }
468	+
469	+                    if (room.AisleColumns.Contains(columnNumber))
470	+                    {
471	+                        throw new InvalidOperationException(
472	+                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt auf einer Gang-Spalte von Raum '{eventDto.RaumId}'.");
473	+                    }
474	+
475	+                    @event.BookingPositions.Add(new BookingPosition
476	+                    {
477	+                        RowLabel = rowLabel,
478	+                        ColumnNumber = columnNumber,
479	+                        BookingId = null,
480	+                        PriceCategoryId = null,
481	+                        CancelledAtUtc = null,
482	+                    });
483	+                }
484	+
485	+                room.Events.Add(@event);
486	+            }
487	+
488	+            venues.Add(venue);
489	+        }
490	+
491	+        db.Venues.AddRange(venues);
492	+        await db.SaveChangesAsync(ct);
493	+    }
494	+
495	+    /// <summary>
496	+    /// `required`-Felder in den Seed-DTOs erzwingen bei System.Text.Json nur die Anwesenheit des
497	+    /// JSON-Schlüssels, nicht dessen Nicht-Null-Wert — ein expliziter JSON-`null`-Wert bleibt also
498	+    /// trotz `required`-Typisierung zur Laufzeit möglich und würde ohne diese Prüfung zu rohen
499	+    /// Ausnahmen (z. B. ArgumentNullException bei Dictionary-Keys) statt einer beschreibenden
500	+    /// Fehlermeldung führen.
501	+    /// </summary>
502	+    private static string RequireNonNull(string? value, string errorMessage) =>
503	+        value ?? throw new InvalidOperationException(errorMessage);
504	+
505	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
506	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
507	+    {
508	+        var digitsStart = 0;
509	+        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
510	+        {
511	+            digitsStart++;
512	+        }
513	+
514	+        var digitsEnd = digitsStart;
515	+        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
516	+        {
517	+            digitsEnd++;
518	+        }
519	+
520	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
521	+            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
522	+        {
523	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
524	+        }
525	+
526	+        var rowLabel = sitzplatz[..digitsStart];
527	+        return (rowLabel, columnNumber);
528	+    }
529	+}
