704	+using System.Reflection;
705	+using seed_a_backend.Api.Domain;
706	+
707	+namespace seed_a_backend.Tests;
708	+
709	+/// <summary>Bewacht AD-5: Domain/ bleibt frei von EF-Core-/ASP.NET-Core-Typen und -Attributen.</summary>
710	+public class DomainDependencyDirectionTests
711	+{
712	+    private static readonly Type[] DomainTypes =
713	+    [
714	+        typeof(Venue), typeof(Room), typeof(Event), typeof(PriceCategory), typeof(Booking), typeof(BookingPosition),
715	+    ];
716	+
717	+    [Fact]
718	+    public void Domain_Typen_haben_keine_Properties_mit_EF_Core_oder_AspNetCore_Typen()
719	+    {
720	+        foreach (var type in DomainTypes)
721	+        {
722	+            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
723	+            {
724	+                Assert.False(IsForbiddenNamespace(property.PropertyType.Namespace),
725	+                    $"{type.Name}.{property.Name} referenziert einen unerlaubten Typ aus '{property.PropertyType.Namespace}'.");
726	+            }
727	+        }
728	+    }
729	+
730	+    [Fact]
731	+    public void Domain_Typen_tragen_keine_Datenannotationen()
732	+    {
733	+        foreach (var type in DomainTypes)
734	+        {
735	+            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
736	+            {
737	+                foreach (var attribute in property.GetCustomAttributes())
738	+                {
739	+                    Assert.False(IsForbiddenNamespace(attribute.GetType().Namespace),
740	+                        $"{type.Name}.{property.Name} trägt ein Attribut aus '{attribute.GetType().Namespace}'.");
741	+                }
742	+            }
743	+        }
744	+    }
745	+
746	+    private static bool IsForbiddenNamespace(string? ns) =>
747	+        ns is not null && (ns.StartsWith("Microsoft.AspNetCore", StringComparison.Ordinal)
748	+            || ns.StartsWith("Microsoft.EntityFrameworkCore", StringComparison.Ordinal)
749	+            || ns.StartsWith("System.ComponentModel.DataAnnotations", StringComparison.Ordinal));
750	+}
