1681	diff --git a/seed-a-backend.Tests/SqlServerTestDatabase.cs b/seed-a-backend.Tests/SqlServerTestDatabase.cs
1682	new file mode 100644
1683	index 0000000..8477bdc
1684	--- /dev/null
1685	+++ b/seed-a-backend.Tests/SqlServerTestDatabase.cs
1686	@@ -0,0 +1,59 @@
1687	+using Microsoft.Data.SqlClient;
1688	+using Microsoft.EntityFrameworkCore;
1689	+using seed_a_backend.Api.Infrastructure;
1690	+
1691	+namespace seed_a_backend.Tests;
1692	+
1693	+/// <summary>
1694	+/// Erstellt für jede Testklasse eine eigene, eindeutig benannte Testdatenbank auf dem echten
1695	+/// SQL Server aus ConnectionStrings__Default (Consistency Convention „Test-Engine für
1696	+/// Nebenläufigkeit“ — kein EF-Core-InMemory-Provider, da gefilterte Unique-Constraints sonst
1697	+/// nicht durchgesetzt würden). Schema wird über die echten EF-Core-Migrations aufgebaut, damit
1698	+/// die Migration selbst mitgetestet wird.
1699	+/// </summary>
1700	+public sealed class SqlServerTestDatabase : IAsyncLifetime
1701	+{
1702	+    private readonly string _connectionString;
1703	+
1704	+    public SqlServerTestDatabase()
1705	+    {
1706	+        _connectionString = CreateIsolatedConnectionString();
1707	+    }
1708	+
1709	+    /// <summary>
1710	+    /// Baut eine eigene, per GUID benannte Connection String für eine isolierte Testdatenbank —
1711	+    /// wiederverwendbar für Tests, die (anders als diese Klasse) die Datenbank nicht vorab per
1712	+    /// Migration anlegen dürfen, weil genau das Anlegen selbst Teil des zu testenden Verhaltens ist.
1713	+    /// </summary>
1714	+    public static string CreateIsolatedConnectionString()
1715	+    {
1716	+        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
1717	+            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");
1718	+
1719	+        var builder = new SqlConnectionStringBuilder(baseConnectionString)
1720	+        {
1721	+            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
1722	+        };
1723	+        return builder.ConnectionString;
1724	+    }
1725	+
1726	+    public AppDbContext CreateContext()
1727	+    {
1728	+        var options = new DbContextOptionsBuilder<AppDbContext>()
1729	+            .UseSqlServer(_connectionString)
1730	+            .Options;
1731	+        return new AppDbContext(options);
1732	+    }
1733	+
1734	+    public async ValueTask InitializeAsync()
1735	+    {
1736	+        await using var db = CreateContext();
1737	+        await db.Database.MigrateAsync();
1738	+    }
1739	+
1740	+    public async ValueTask DisposeAsync()
1741	+    {
1742	+        await using var db = CreateContext();
1743	+        await db.Database.EnsureDeletedAsync();
1744	+    }
1745	+}
