382	+                }
383	+
384	+                venue.Rooms.Add(roomsById[roomId]);
385	+            }
386	+
387	+            foreach (var eventDto in veranstaltungen.Where(e => e.SpielstaetteId == venueId))
388	+            {
389	+                var raumId = RequireNonNull(eventDto.RaumId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Raum-Id.");
390	+                if (!roomsById.TryGetValue(raumId, out var room))
391	+                {
392	+                    throw new InvalidOperationException(
393	+                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{raumId}' in Spielstätte '{venueId}'.");
394	+                }
395	+
396	+                if (eventDto.DauerMinuten < 1)
397	+                {
398	+                    throw new InvalidOperationException(
399	+                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Dauer ({eventDto.DauerMinuten} Minuten); erwartet wird mindestens 1.");
400	+                }
401	+
402	+                if (eventDto.Altersfreigabe < 0)
403	+                {
404	+                    throw new InvalidOperationException(
405	+                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Altersfreigabe ({eventDto.Altersfreigabe}); negative Werte sind nicht erlaubt.");
406	+                }
407	+
408	+                var @event = new Event
409	+                {
410	+                    Titel = RequireNonNull(eventDto.Titel, $"Veranstaltung '{eventDto.Id}' hat einen fehlenden (null) Titel."),
411	+                    Beschreibung = RequireNonNull(eventDto.Beschreibung, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Beschreibung."),
412	+                    Zeitpunkt = eventDto.Zeitpunkt,
413	+                    DauerMinuten = eventDto.DauerMinuten,
414	+                    Altersfreigabe = eventDto.Altersfreigabe,
415	+                };
416	+
417	+                var preiskategorien = eventDto.Preiskategorien
418	+                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'preiskategorien'-Feld.");
419	+
420	+                foreach (var priceCategoryDto in preiskategorien)
421	+                {
422	+                    if (priceCategoryDto.Preis < 0)
423	+                    {
424	+                        throw new InvalidOperationException(
425	+                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen negativen Preis ({priceCategoryDto.Preis}).");
426	+                    }
427	+
428	+                    @event.PriceCategories.Add(new PriceCategory
429	+                    {
430	+                        Name = RequireNonNull(
431	+                            priceCategoryDto.Name,
432	+                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen fehlenden (null) Namen."),
433	+                        Preis = priceCategoryDto.Preis,
