150	+    {
151	+        modelBuilder.Entity<Venue>(entity =>
152	+        {
153	+            entity.HasMany(v => v.Rooms)
154	+                .WithOne()
155	+                .HasForeignKey(r => r.VenueId)
156	+                .OnDelete(DeleteBehavior.Restrict);
157	+        });
158	+
159	+        modelBuilder.Entity<Room>(entity =>
160	+        {
161	+            entity.HasMany(r => r.Events)
162	+                .WithOne()
163	+                .HasForeignKey(e => e.RoomId)
164	+                .OnDelete(DeleteBehavior.Restrict);
165	+
166	+            entity.Property(r => r.RowLabels)
167	+                .HasConversion(
168	+                    v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
169	+                    v => JsonSerializer.Deserialize<List<string>>(v, JsonSerializerOptions.Default) ?? new List<string>())
170	+                .Metadata.SetValueComparer(new ValueComparer<IReadOnlyList<string>>(
171	+                    (a, b) => (a ?? new List<string>()).SequenceEqual(b ?? new List<string>()),
172	+                    v => (v ?? new List<string>()).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
173	+                    v => (v ?? new List<string>()).ToList()));
174	+
175	+            entity.Property(r => r.AisleColumns)
176	+                .HasConversion(
177	+                    v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
178	+                    v => JsonSerializer.Deserialize<List<int>>(v, JsonSerializerOptions.Default) ?? new List<int>())
179	+                .Metadata.SetValueComparer(new ValueComparer<IReadOnlyCollection<int>>(
180	+                    (a, b) => (a ?? new List<int>()).SequenceEqual(b ?? new List<int>()),
181	+                    v => (v ?? new List<int>()).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
182	+                    v => (v ?? new List<int>()).ToList()));
183	+        });
184	+
185	+        modelBuilder.Entity<Event>(entity =>
186	+        {
187	+            entity.HasMany(e => e.PriceCategories)
188	+                .WithOne()
189	+                .HasForeignKey(pc => pc.EventId)
190	+                .OnDelete(DeleteBehavior.Restrict);
191	+
192	+            entity.HasMany(e => e.BookingPositions)
193	+                .WithOne()
194	+                .HasForeignKey(bp => bp.EventId)
195	+                .OnDelete(DeleteBehavior.Restrict);
196	+        });
197	+
198	+        modelBuilder.Entity<PriceCategory>(entity =>
199	+        {
200	+            entity.Property(pc => pc.Preis).HasPrecision(10, 2);
201	+        });
202	+
203	+        modelBuilder.Entity<Booking>(entity =>
204	+        {
205	+            entity.Property(b => b.Reference)
206	+                .HasMaxLength(8)
207	+                .IsRequired()
208	+                .UseCollation("SQL_Latin1_General_CP1_CI_AS");
209	+            entity.HasIndex(b => b.Reference).IsUnique();
210	+
211	+            entity.HasMany(b => b.Positions)
212	+                .WithOne()
