273	+    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
274	+    {
275	+        if (await db.Venues.AnyAsync(ct))
276	+        {
277	+            return;
278	+        }
279	+
280	+        if (!File.Exists(jsonFilePath))
281	+        {
282	+            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' wurde nicht gefunden.");
283	+        }
284	+
285	+        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
