291	+        catch (JsonException ex)
292	+        {
293	+            throw new InvalidOperationException(
294	+                $"Anfangsdatenbestand '{jsonFilePath}' konnte nicht gelesen werden: {ex.Message}", ex);
295	+        }
296	+
297	+        if (data is null)
298	+        {
299	+            throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
300	+        }
301	+
302	+        await ImportAsync(data, ct);
