305	+    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
306	+    {
307	+        var spielstaetten = data.Spielstaetten
308	+            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'spielstaetten'-Feld.");
309	+        var veranstaltungen = data.Veranstaltungen
310	+            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'veranstaltungen'-Feld.");
311	+
312	+        var venueIds = new HashSet<string>();
313	+        foreach (var venueDto in spielstaetten)
314	+        {
315	+            var venueId = RequireNonNull(venueDto.Id, "Anfangsdatenbestand enthält eine Spielstätte mit fehlender (null) Id.");
316	+            if (!venueIds.Add(venueId))
317	+            {
318	+                throw new InvalidOperationException($"Spielstätte '{venueId}' ist im Anfangsdatenbestand mehrfach vorhanden.");
319	+            }
320	+        }
321	+
322	+        foreach (var eventDto in veranstaltungen)
323	+        {
324	+            var spielstaetteId = RequireNonNull(eventDto.SpielstaetteId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Spielstätten-Id.");
325	+            if (!venueIds.Contains(spielstaetteId))
326	+            {
327	+                throw new InvalidOperationException(
328	+                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{spielstaetteId}'.");
329	+            }
330	+        }
331	+
332	+        var venues = new List<Venue>();
333	+
334	+        foreach (var venueDto in spielstaetten)
335	+        {
