337	+            var venueName = RequireNonNull(venueDto.Name, $"Spielstätte '{venueId}' hat einen fehlenden (null) Namen.");
338	+            var venue = new Venue { Name = venueName };
339	+            var roomsById = new Dictionary<string, Room>();
340	+
341	+            var raeume = venueDto.Raeume
342	+                ?? throw new InvalidOperationException($"Spielstätte '{venueId}' enthält kein 'raeume'-Feld.");
343	+
344	+            foreach (var roomDto in raeume)
345	+            {
346	+                var roomId = RequireNonNull(roomDto.Id, $"Spielstätte '{venueId}' enthält einen Raum mit fehlender (null) Id.");
