358	+                    if (column < 1 || column > roomDto.Spalten)
359	+                    {
360	+                        throw new InvalidOperationException(
361	+                            $"Raum '{roomId}': Gang-Spalte '{column}' liegt außerhalb des Sitzplans (1..{roomDto.Spalten}).");
362	+                    }
363	+                }
364	+
365	+                var reihen = roomDto.Reihen
366	+                    ?? throw new InvalidOperationException($"Raum '{roomId}' in Spielstätte '{venueId}' enthält kein 'reihen'-Feld.");
367	+                var rowLabels = reihen
368	+                    .Select(rowLabel => RequireNonNull(
369	+                        rowLabel, $"Raum '{roomId}' in Spielstätte '{venueId}' enthält einen leeren (null) Eintrag in 'reihen'."))
370	+                    .ToList();
371	+
372	+                if (!roomsById.TryAdd(roomId, new Room
373	+                {
374	+                    Name = roomName,
375	+                    RowLabels = rowLabels,
376	+                    ColumnCount = roomDto.Spalten,
377	+                    AisleColumns = aisleColumns,
378	+                }))
379	+                {
