473	+                    }
474	+
475	+                    @event.BookingPositions.Add(new BookingPosition
476	+                    {
477	+                        RowLabel = rowLabel,
478	+                        ColumnNumber = columnNumber,
479	+                        BookingId = null,
480	+                        PriceCategoryId = null,
481	+                        CancelledAtUtc = null,
482	+                    });
483	+                }
484	+
485	+                room.Events.Add(@event);
