495	+    /// <summary>
496	+    /// `required`-Felder in den Seed-DTOs erzwingen bei System.Text.Json nur die Anwesenheit des
497	+    /// JSON-Schlüssels, nicht dessen Nicht-Null-Wert — ein expliziter JSON-`null`-Wert bleibt also
498	+    /// trotz `required`-Typisierung zur Laufzeit möglich und würde ohne diese Prüfung zu rohen
499	+    /// Ausnahmen (z. B. ArgumentNullException bei Dictionary-Keys) statt einer beschreibenden
500	+    /// Fehlermeldung führen.
501	+    /// </summary>
502	+    private static string RequireNonNull(string? value, string errorMessage) =>
503	+        value ?? throw new InvalidOperationException(errorMessage);
504	+
505	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
506	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
507	+    {
508	+        var digitsStart = 0;
509	+        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
510	+        {
511	+            digitsStart++;
512	+        }
513	+
514	+        var digitsEnd = digitsStart;
515	+        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
516	+        {
517	+            digitsEnd++;
518	+        }
519	+
520	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
521	+            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
522	+        {
523	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
524	+        }
525	+
526	+        var rowLabel = sitzplatz[..digitsStart];
527	+        return (rowLabel, columnNumber);
528	+    }
529	+}
